INSERT INTO public.agents VALUES ('infographic-agent', '{marketing}', 'Infographic Agent', 'Creates professional infographics from any topic or input. Transforms complex information into visually appealing, easy-to-understand graphics.', 'media', 'marketing', '{infographic,marketing,visualization,media,design}', '{"input_modes": ["text/plain", "application/json"], "output_modes": ["image/png", "image/jpeg"]}', NULL, '{"model": "gpt-image-1", "provider": "openai"}', '{"status": "active", "mediaType": "image", "defaultModel": "gpt-image-1", "defaultProvider": "openai", "supportedModels": {"google": ["imagen-4.0-generate-001", "imagen-4.0-ultra-generate-001"], "openai": ["gpt-image-1.5", "gpt-image-1"]}, "promptEnhancement": {"enabled": true, "template": "Create a professional infographic about: {topic}. Style: {style}. Layout: {orientation}. Include clear sections with icons and visual hierarchy."}, "supportedProviders": ["openai", "google"], "executionCapabilities": {"canPlan": false, "canBuild": true, "canConverse": false}}', '2026-03-15 17:21:17.951984+00', '2026-03-15 18:47:37.652264+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('general-assistant', '{global}', 'General Assistant', 'A helpful AI assistant for open-ended conversations. Can discuss any topic, answer questions, help with analysis, and process uploaded documents and images.', 'context', 'general', '{chat,conversation,general-purpose,assistant,multimodal}', '{"system_prompt": "You are a helpful, knowledgeable AI assistant. You can discuss any topic, answer questions, help with analysis and writing, and process uploaded documents and images.\n\nWhen documents are uploaded, carefully read and reference the extracted text provided in the prompt.\n\nWhen images are uploaded, describe what you see and answer questions about the visual content.\n\nBe conversational, accurate, and helpful. Ask clarifying questions when the user''s intent is ambiguous.", "conversation_guidelines": "Be friendly and professional. Provide thorough but concise answers. Use markdown formatting when it improves readability. Cite specific parts of uploaded documents when referencing them."}', NULL, '{"maxTokens": 4000, "temperature": 0.7}', '{"status": "active", "multimodal": {"vision_capable": true, "supports_images": true, "supports_documents": true}, "execution_modes": ["immediate"], "execution_profile": "conversation_only", "execution_capabilities": {"can_plan": false, "can_build": false, "can_converse": true, "requires_human_gate": false}}', '2026-03-15 17:21:18.591001+00', '2026-03-15 18:47:37.652264+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('extended-post-writer', '{marketing}', 'Extended Post Writer', 'LangGraph-powered content generation agent with Human-in-the-Loop (HITL) approval. Generates blog posts, SEO descriptions, and social media posts, then pauses for human review before finalizing.', 'langgraph', 'marketing', '{content-creation,blog,seo,social-media,langgraph,hitl}', '{"markdown": "# Extended Post Writer Agent\n\nA LangGraph-powered content generation agent with Human-in-the-Loop (HITL) approval workflow.\n\n## Capabilities\n- **Blog Post Generation**: Creates comprehensive blog posts on any topic\n- **SEO Description**: Generates optimized meta descriptions\n- **Social Media Posts**: Creates multiple social media posts for different platforms\n- **HITL Approval**: Pauses for human review before finalizing content\n\n## HITL Workflow\n1. User provides topic and preferences\n2. Agent generates all content types\n3. Workflow pauses with `hitl_waiting` status\n4. Human reviews content in approval modal\n5. Human can:\n   - **Approve**: Accept content as-is\n   - **Edit**: Modify content then approve\n   - **Reject**: Reject and provide feedback\n6. Workflow completes with final content\n\n## Resume Actions\n- `approve`: Accept generated content\n- `edit`: Accept with modifications (provide editedContent)\n- `reject`: Reject content (provide feedback)\n\n## Endpoints\n- `POST /extended-post-writer/generate` - Start generation\n- `POST /extended-post-writer/resume/:threadId` - Resume with decision\n- `GET /extended-post-writer/status/:threadId` - Check status"}', NULL, '{"model": "llama3.2:1b", "provider": "ollama"}', '{"status": "disabled", "features": ["hitl", "checkpointing", "content-generation"], "provider": "langgraph", "hitlEnabled": true, "resumeEndpoint": "/extended-post-writer/resume/{threadId}", "statusEndpoint": "/extended-post-writer/status/{threadId}", "execution_modes": ["immediate", "polling", "real-time"], "forwardConverse": false, "historyEndpoint": "/extended-post-writer/history/{threadId}", "langgraphEndpoint": "http://localhost:6200", "execution_capabilities": {"can_plan": false, "can_build": true, "can_converse": false, "requires_human_gate": true}}', '2026-03-15 17:21:17.880372+00', '2026-03-18 19:12:14.823008+00', false, 'text', 'archived');
INSERT INTO public.agents VALUES ('hr-assistant', '{human-resources}', 'HR Assistant', 'Answers questions about HR policies, employee handbooks, benefits, and workplace guidelines with proper citations.', 'rag', 'human-resources', '{hr,policy,benefits,employee,handbook,rag}', 'You are an HR Assistant. Answer questions about human resources policies, employee benefits, workplace guidelines, and company handbooks using the knowledge base. Always cite the source document when providing information. Be helpful and clear, but remind users to consult HR directly for sensitive or case-specific matters.', NULL, '{"model": "claude-sonnet-4-6", "provider": "anthropic", "parameters": {"maxTokens": 2000, "temperature": 0.3}}', '{"author": "Orchestrator AI Team", "status": "active", "license": "MIT", "rag_config": {"top_k": 5, "collection_slug": "hr-policy", "no_access_message": "I do not have access to the HR knowledge base.", "no_results_message": "I could not find relevant HR policy information. Please contact your HR representative directly.", "similarity_threshold": 0.3}}', '2026-03-15 17:21:18.634614+00', '2026-03-17 20:33:54.306736+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('video-generator', '{marketing}', 'Video Generator', 'Generates high-quality videos using AI models from OpenAI (Sora 2) and Google (Veo 3). Supports various durations, aspect ratios, and resolutions. Video generation is asynchronous and may take several minutes.', 'media', 'creative', '{video,generation,creative,media,ai-video,sora,veo}', '{"input_modes": ["text/plain", "image/png", "image/jpeg"], "output_modes": ["video/mp4", "video/webm"]}', NULL, '{"model": "sora-2", "provider": "openai"}', '{"status": "active", "mediaType": "video", "defaultModel": "sora-2", "asyncGeneration": true, "defaultProvider": "openai", "supportedModels": {"google": ["veo-3-generate"], "openai": ["sora-2"]}, "supportedProviders": ["openai", "google"], "executionCapabilities": {"canPlan": false, "canBuild": true, "canConverse": false}, "estimatedProcessingTime": "2-10 minutes depending on duration and resolution"}', '2026-03-15 17:21:17.954848+00', '2026-03-18 19:23:53.586388+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('legal-policies-agent', '{legal}', 'Confidentiality Assistant', 'Answers questions about client confidentiality policies with proper citations [FP-001, Section 2.1].', 'rag', 'legal', '{legal,policy,compliance,attributed,rag}', 'You are a Confidentiality Assistant. Answer questions about client confidentiality policies using the knowledge base. Always cite sources using document ID and section (e.g., [FP-001, Article II]).', NULL, '{"model": "gpt-oss:20b", "provider": "ollama", "parameters": {"maxTokens": 2000, "temperature": 0.3}}', '{"author": "Orchestrator AI Team", "status": "active", "license": "MIT", "rag_config": {"top_k": 5, "collection_slug": "law-firm-policies-attributed", "no_access_message": "I do not have access to the firm policies knowledge base.", "no_results_message": "I could not find relevant policy information. Please consult the policy manual directly.", "similarity_threshold": 0.6}}', '2026-03-15 17:21:18.057286+00', '2026-03-17 20:33:54.306736+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('legal-litigation-agent', '{legal}', 'Litigation Assistant', 'Provides litigation guidance with cross-referenced documents. Links related checklists (motions → discovery → depositions → trial).', 'rag', 'legal', '{legal,litigation,motions,discovery,cross-reference,rag}', 'You are a Legal Litigation Assistant. Provide guidance on litigation procedures. Always mention related documents (e.g., "See also: Written Discovery Checklist [LIT-002]").', NULL, '{"model": "gpt-oss:20b", "provider": "ollama", "parameters": {"maxTokens": 2000, "temperature": 0.3}}', '{"author": "Orchestrator AI Team", "status": "active", "license": "MIT", "rag_config": {"top_k": 5, "collection_slug": "law-litigation-cross-reference", "no_access_message": "I do not have access to the litigation knowledge base.", "no_results_message": "I could not find relevant litigation guidance.", "similarity_threshold": 0.6}}', '2026-03-15 17:21:18.057286+00', '2026-03-17 20:33:54.306736+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('legal-contracts-agent', '{legal}', 'Contracts Assistant', 'Finds contract clauses and templates using hybrid search (keyword + semantic). Great for finding specific terms like "indemnification" or "limitation of liability".', 'rag', 'legal', '{legal,contracts,templates,clauses,hybrid,rag}', 'You are a Legal Contracts Assistant. Use hybrid search to find relevant contract clauses. Indicate whether matches are keyword-based (exact terms), semantic (meaning-based), or both.', NULL, '{"model": "gpt-oss:20b", "provider": "ollama", "parameters": {"maxTokens": 2000, "temperature": 0.3}}', '{"author": "Orchestrator AI Team", "status": "active", "license": "MIT", "rag_config": {"top_k": 8, "collection_slug": "law-contracts-hybrid", "no_access_message": "I do not have access to the contracts knowledge base.", "no_results_message": "I could not find relevant clauses. Consider using different search terms.", "similarity_threshold": 0.5}}', '2026-03-15 17:21:18.057286+00', '2026-03-17 20:33:54.306736+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('legal-department', '{legal}', 'Department AI', 'Multi-agent legal document analysis system. Processes contracts, NDAs, MSAs, and legal documents using CLO routing, specialist agents (contract, compliance, IP), and synthesis. Supports multimodal input for scanned/PDF documents.', 'langgraph', 'legal', '{legal-analysis,contract-review,compliance,ip-law,multimodal,langgraph,multi-agent}', '{"markdown": "Department AI - Multi-agent legal document analysis system"}', NULL, NULL, '{"status": "disabled", "provider": "langgraph", "framework": "langgraph", "hasCustomUI": true, "forwardConverse": true, "customUIComponent": "legal-department", "langgraphWorkflow": "legal-department"}', '2026-03-15 17:21:18.445214+00', '2026-03-18 19:12:14.807298+00', false, 'text', 'archived');
INSERT INTO public.agents VALUES ('predictor', '{finance}', 'Predictor Agent', 'LangGraph-based prediction agent that processes articles for signal generation, evaluates predictor priority, and generates predictions for financial instruments.', 'langgraph', 'finance', '{prediction,signal-generation,financial-analysis}', 'Predictor agent for the event-driven prediction pipeline. Receives triggers from Pulse DB watchers when articles are inserted or predictors are created.', NULL, NULL, '{"hidden": true, "status": "archived"}', '2026-03-15 23:46:20.986198+00', '2026-03-18 19:13:22.096698+00', false, 'text', 'archived');
INSERT INTO public.agents VALUES ('legal-estate-agent', '{legal}', 'Estate Planning Assistant', 'Provides estate planning guidance with proper citations. Covers wills, trusts, POAs, and healthcare directives.', 'rag', 'legal', '{legal,estate,wills,trusts,attributed,rag}', 'You are a Legal Estate Planning Assistant. Answer questions about estate planning using the knowledge base. Always cite sources using document ID and section.', NULL, '{"model": "gpt-oss:20b", "provider": "ollama", "parameters": {"maxTokens": 2000, "temperature": 0.3}}', '{"author": "Orchestrator AI Team", "status": "active", "license": "MIT", "rag_config": {"top_k": 5, "collection_slug": "law-estate-planning-attributed", "no_access_message": "I do not have access to the estate planning knowledge base.", "no_results_message": "I could not find relevant estate planning information.", "similarity_threshold": 0.6}}', '2026-03-15 17:21:18.057286+00', '2026-03-17 20:33:54.306736+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('us-tech-stocks', '{finance}', 'US Tech Stocks Predictor', 'Ambient prediction agent that continuously monitors major US technology stocks (AAPL, MSFT, GOOGL, NVDA, META, AMZN, TSLA) and generates trading recommendations based on technical and fundamental analysis.', 'prediction', 'finance', '{stocks,prediction,tech,ambient-agent,trading,market-analysis}', '{"markdown": "# US Tech Stocks Predictor\n\nAn ambient prediction agent that continuously monitors major US technology stocks and generates trading recommendations.\n\n## Tracked Instruments\n- AAPL (Apple Inc.)\n- MSFT (Microsoft Corporation)\n- GOOGL (Alphabet Inc.)\n- NVDA (NVIDIA Corporation)\n- META (Meta Platforms)\n- AMZN (Amazon)\n- TSLA (Tesla)\n\n## Risk Profiles\n- Conservative: Smaller positions, higher confidence threshold\n- Moderate (default): Balanced risk-reward\n- Aggressive: Larger positions, lower confidence threshold"}', '{"url": "http://localhost:3000/api/v1/predictions/agents/us-tech-stocks-2025"}', '{"model": "claude-sonnet-4-20250514", "provider": "anthropic", "temperature": 0.3}', '{"runner": "stock-predictor", "status": "disabled", "hasCustomUI": true, "runnerConfig": {"runner": "financial-asset-predictor", "instruments": ["AAPL", "MSFT", "GOOGL", "NVDA", "META", "AMZN", "TSLA"], "riskProfile": "moderate", "pollIntervalMs": 60000}, "customUIComponent": "prediction-dashboard", "executionCapabilities": {"canPlan": false, "canBuild": false, "canConverse": false, "isDashboard": true, "requiresHumanGate": false}}', '2026-03-15 17:21:18.102313+00', '2026-03-18 19:13:22.129266+00', false, 'text', 'archived');
INSERT INTO public.agents VALUES ('legal-intake-agent', '{legal}', 'Intake Assistant', 'Provides client intake guidance with version tracking. Shows what changed between document versions (v1.0 vs v2.0).', 'rag', 'legal', '{legal,intake,client,versions,temporal,rag}', 'You are a Legal Intake Assistant. Help with client intake procedures. When relevant, indicate document versions and highlight changes between versions.', NULL, '{"model": "gpt-oss:20b", "provider": "ollama", "parameters": {"maxTokens": 2000, "temperature": 0.3}}', '{"author": "Orchestrator AI Team", "status": "active", "license": "MIT", "rag_config": {"top_k": 5, "collection_slug": "law-client-intake-temporal", "no_access_message": "I do not have access to the intake knowledge base.", "no_results_message": "I could not find relevant intake procedures.", "similarity_threshold": 0.4}}', '2026-03-15 17:21:18.057286+00', '2026-03-18 19:56:48.976132+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('marketing-swarm', '{marketing}', 'Marketing Swarm', 'Multi-agent marketing content generation system. Uses multiple writer agents to create drafts, editor agents for review cycles, and evaluator agents to score outputs. Compares different LLM and personality combinations.', 'langgraph', 'marketing', '{content-creation,multi-agent,swarm,marketing,langgraph}', '{"markdown": "# Marketing Swarm Agent\n\nA sophisticated multi-agent system for generating high-quality marketing content through collaboration and competition.\n\n## How It Works\n\n1. **Configuration**: Select content type, provide prompts, choose writer/editor/evaluator agents with LLM configurations\n2. **Writing Phase**: Multiple writer agents generate initial drafts in parallel (or sequentially for local LLMs)\n3. **Editing Phase**: Each draft is reviewed by selected editors (up to 5 revision cycles until approved)\n4. **Evaluation Phase**: All approved outputs are scored by evaluator agents\n5. **Ranking**: Outputs are ranked by weighted evaluation scores\n\n## Key Features\n\n- **Personality + LLM Separation**: Same agent personality can use different LLMs for comparison\n- **Multiplicative Combinations**: Writers x Editors x LLMs = comprehensive content exploration\n- **Iterative Refinement**: Edit cycles continue until editor approves or max cycles reached\n- **Full Audit Trail**: Every draft, revision, and evaluation is stored for analysis\n- **Reconnection Support**: Resume viewing progress from database state\n\n## Custom UI\n\nThis agent has a custom UI at `/agents/{org}/marketing-swarm` that provides:\n- Interactive configuration wizard\n- Real-time progress dashboard with agent cards\n- Side-by-side content comparison\n- Detailed audit trail viewer\n\n## SSE Progress Events\n\nThe agent streams progress via SSE messages:\n- `queue_built`: Initial execution plan ready\n- `step_started`: Agent beginning work\n- `step_completed`: Agent finished with results\n- `edit_cycle_added`: New revision cycle needed\n- `phase_changed`: Major workflow phase transition\n- `error`: Something went wrong"}', NULL, NULL, '{"status": "disabled", "features": ["multi-agent", "swarm", "sse-streaming", "custom-ui"], "provider": "langgraph", "hasCustomUI": true, "dashboardType": "custom", "statusEndpoint": "/marketing-swarm/status/{taskId}", "interaction_mode": "dashboard", "customUIComponent": "marketing-swarm", "langgraphEndpoint": "http://localhost:6200", "execution_capabilities": {"can_plan": false, "can_build": true, "can_converse": false, "requires_human_gate": false}}', '2026-03-15 17:21:18.523498+00', '2026-03-18 19:12:14.834916+00', false, 'text', 'archived');
INSERT INTO public.agents VALUES ('cad-agent', '{engineering,global}', 'CAD Agent', 'LangGraph-powered CAD agent that generates parametric 3D CAD models from natural language descriptions. Uses OpenCASCADE.js for geometry creation and exports to STEP, STL, GLTF formats. Includes custom UI with 3D viewer.', 'langgraph', 'engineering', '{cad,3d-modeling,parametric,engineering,opencascade,langgraph,custom-ui}', '{"markdown": "# CAD Agent\n\nA LangGraph-powered agent that generates parametric 3D CAD models from natural language descriptions.\n\n## Capabilities\n- **Code Generation**: Uses qwen2.5-coder to generate OpenCASCADE.js code\n- **Geometry Execution**: Runs generated code in Node.js WASM environment\n- **Multi-Format Export**: Exports to STEP, STL, GLTF, DXF\n- **Constraint Application**: Respects project-wide and per-drawing constraints\n\n## Workflow\n1. Receive natural language prompt\n2. Apply project constraints to prompt\n3. Generate OpenCASCADE.js code with LLM\n4. Validate TypeScript code\n5. Execute code in WASM environment\n6. Export to multiple formats\n7. Store files in Supabase storage\n\n## Custom UI\nThis agent has a custom UI with:\n- Config tab: Set project constraints\n- Progress tab: Real-time generation progress via SSE\n- Deliverables tab: 3D viewer for GLTF, download buttons for all formats"}', NULL, '{"model": "qwen2.5-coder:14b", "provider": "ollama", "parameters": {"maxTokens": 4000, "temperature": 0.7}}', '{"status": "disabled", "features": ["code-generation", "wasm-execution", "multi-format-export", "3d-viewer", "constraint-system"], "provider": "langgraph", "streaming": {"enabled": true, "eventTypes": ["prompt_received", "constraints_applied", "llm_started", "llm_completed", "code_validation", "execution_started", "execution_completed", "export_started", "export_completed"]}, "hasCustomUI": true, "langgraphPath": "agents/engineering/cad-agent", "supportedFormats": ["step", "stl", "gltf", "dxf"], "customUIComponent": "cad-agent", "langgraphWorkflow": "cad-agent", "defaultConstraints": {"units": "mm", "material": "Aluminum 6061", "tolerance_class": "standard", "wall_thickness_min": 2.0, "manufacturing_method": "CNC"}, "executionCapabilities": {"canPlan": false, "canBuild": true, "canConverse": true, "requiresHumanGate": false}}', '2026-03-15 17:21:18.031519+00', '2026-03-18 19:12:14.847328+00', false, 'text', 'archived');
INSERT INTO public.agents VALUES ('image-generator', '{marketing}', 'Image Generator', 'Generates high-quality images using AI models from OpenAI (GPT Image, DALL-E) and Google (Imagen 4). Supports various sizes, styles, and quality settings.', 'media', 'creative', '{image,generation,creative,media,ai-art}', '{"input_modes": ["text/plain"], "output_modes": ["image/png", "image/jpeg", "image/webp"]}', NULL, '{"model": "gpt-image-1", "provider": "openai"}', '{"status": "active", "mediaType": "image", "defaultModel": "gpt-image-1", "defaultProvider": "openai", "supportedModels": {"google": ["imagen-4.0-generate-001", "imagen-4.0-ultra-generate-001"], "openai": ["gpt-image-1.5", "gpt-image-1"]}, "supportedProviders": ["openai", "google"], "executionCapabilities": {"canPlan": false, "canBuild": true, "canConverse": false}}', '2026-03-15 17:21:17.951151+00', '2026-03-18 19:23:53.565264+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('investment-risk-agent', '{finance}', 'Investment Risk Analyzer', 'Multi-dimensional risk analysis agent that provides comprehensive risk assessments for investment portfolios using Risk Radar analysis, Red Team/Blue Team debate, and continuous learning from outcomes.', 'risk', 'finance', '{risk,investment,analysis,portfolio,risk-radar,debate,learning}', '{"markdown": "# Investment Risk Analyzer\n\nA multi-dimensional risk analysis agent that provides comprehensive risk assessments.\n\n## Features\n- **Risk Radar**: Parallel analysis across multiple risk dimensions\n- **Red Team/Blue Team**: Adversarial debate for balanced assessment\n- **Learning Loop**: Continuous improvement from outcome tracking\n- **Custom Dimensions**: Table-driven, configurable risk factors\n\n## Risk Dimensions\n- Market Risk: Price volatility, market conditions\n- Credit Risk: Counterparty and default risk\n- Liquidity Risk: Market depth, trading volume\n- Operational Risk: Business and execution risks\n- Regulatory Risk: Compliance and legal risks\n- Concentration Risk: Portfolio diversification\n\n## Analysis Process\n1. Parallel dimension analysis with specialized prompts\n2. Weighted score aggregation\n3. Optional adversarial debate for high-risk scores\n4. Learning from actual outcomes"}', '{"url": "http://localhost:3000/api/v1/risk/agents/investment-risk-agent"}', '{"model": "claude-sonnet-4-20250514", "provider": "anthropic", "temperature": 0.3}', '{"runner": "risk-analyzer", "status": "disabled", "hasCustomUI": true, "runnerConfig": {"runner": "risk-analyzer", "alertThreshold": 0.8, "debateThreshold": 0.7, "analysisIntervalMs": 1800000}, "customUIComponent": "investment-risk-dashboard", "executionCapabilities": {"canPlan": false, "canBuild": false, "canConverse": false, "isDashboard": true, "requiresHumanGate": false}}', '2026-03-15 17:21:18.392957+00', '2026-03-18 19:13:22.113692+00', false, 'text', 'archived');
INSERT INTO public.agents VALUES ('customer-service', '{global}', 'Customer Service', 'AI-powered customer service agent for Orchestrator AI. Answers questions about the platform, pricing, and how to get started. Supports both text and voice interaction modes.', 'langgraph', 'customer-service', '{customer-service,voice,text,support,langgraph}', 'You are the Orchestrator AI assistant. You answer questions about the Orchestrator AI platform, explain pricing, help visitors understand use cases, and guide them toward getting started. You are friendly, concise, and professional. In voice mode, keep responses to 2-3 sentences. Never make up features or pricing not in your knowledge base. When unsure, provide contact info: hello@orchestrator-ai.com or 763-220-0146.', NULL, '{"model": "claude-sonnet-4-6", "provider": "anthropic", "parameters": {"maxTokens": 1000, "temperature": 0.7}}', '{"author": "Orchestrator AI Team", "status": "disabled", "license": "MIT", "provider": "langgraph", "framework": "langgraph", "supportsVoice": true, "forwardConverse": true}', '2026-03-15 17:21:18.654322+00', '2026-03-18 19:23:53.604006+00', false, 'text', 'active');
INSERT INTO public.agents VALUES ('hr-assistant-langgraph', '{human-resources}', 'HR Assistant (LangGraph)', 'LangGraph conversion of HR Assistant. Answers questions about human resources policies, employee benefits, workplace guidelines, and company handbooks using the knowledge base.', 'api', 'human-resources', '{hr,policy,benefits,employee,handbook,rag,langgraph,converted}', 'You are an HR Assistant. Answer questions about human resources policies, employee benefits, workplace guidelines, and company handbooks using the knowledge base. Always cite the source document when providing information. Be helpful and clear, but remind users to consult HR directly for sensitive or case-specific matters.', '{"url": "http://localhost:6200/conversions/hr-assistant/execute", "method": "POST", "timeout": 120000}', NULL, '{"status": "disabled", "features": ["stateful", "checkpointing", "rag-retrieval"], "provider": "langgraph", "originalType": "rag-runner", "convertedFrom": "hr-assistant"}', '2026-03-15 17:21:18.635645+00', '2026-03-18 19:25:25.149429+00', false, 'text', 'archived');
